-- T2 export candidate; generated OFFLINE from reviewed fixture + Step 9A + explicit P0-05 lock candidate. No live drift inputs.
-- Apply account-data-export-collect-battle-v1.sql before this contract.
-- Base: market-production-trade-lock-v1.sql in the same release transaction. Legal semantics stay v1.2; security contract is separately versioned.
begin;
create or replace function public.get_security_schema_readiness_v1() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
 declare actual jsonb;begin with checks as (
 select 'relation' k,n.nspname||'.'||c.relname name,jsonb_build_object('kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'options',c.reloptions,
 'rights',(select jsonb_agg(jsonb_build_array(r,v,case when c.relkind='S' then has_sequence_privilege(r,c.oid,v) else has_table_privilege(r,c.oid,v) end) order by r,v)
 from unnest(array['anon','authenticated','service_role']) r cross join lateral unnest(case when c.relkind='S' then array['USAGE','SELECT','UPDATE'] else array['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'] end) v),
 'columns',(select jsonb_agg(jsonb_build_array(r,a.attname,v,has_column_privilege(r,c.oid,a.attnum,v)) order by r,a.attnum,v) from pg_attribute a cross join unnest(array['anon','authenticated','service_role']) r cross join unnest(array['SELECT','INSERT','UPDATE','REFERENCES']) v where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped and c.relkind<>'S'),
 'policies',(select jsonb_agg(jsonb_build_array(p.polname,p.polcmd,p.polpermissive,p.polroles::regrole[]::text[],pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname) from pg_policy p where p.polrelid=c.oid)) v
 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','dv_market_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private','dv_collect_private') and c.relkind in ('r','p','v','m','f','S')
 union all select 'function',n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')',jsonb_build_object('body',md5(p.prosrc),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'result',pg_get_function_result(p.oid),'language',l.lanname,'volatility',p.provolatile,'strict',p.proisstrict,'rights',(select jsonb_agg(jsonb_build_array(r,has_function_privilege(r,p.oid,'EXECUTE')) order by r) from unnest(array['anon','authenticated','service_role']) r))
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','dv_market_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private','dv_collect_private') and p.proname not in ('get_security_schema_readiness_v1','get_market_legal_schema_readiness_v1')
 union all select 'schema',n.nspname,jsonb_agg(jsonb_build_array(r,has_schema_privilege(r,n.oid,'USAGE'),has_schema_privilege(r,n.oid,'CREATE')) order by r) from pg_namespace n cross join unnest(array['anon','authenticated','service_role']) r where n.nspname in ('public','dv_market_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private','dv_collect_private') group by n.oid,n.nspname
 union all select 'defaults',coalesce(n.nspname,'GLOBAL')||'.'||pg_get_userbyid(d.defaclrole)||'.'||d.defaclobjtype::text,jsonb_agg(jsonb_build_array(coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) order by coalesce(r.rolname,'PUBLIC'),a.privilege_type)
 from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) a left join pg_roles r on r.oid=a.grantee where d.defaclrole='postgres'::regrole and (n.nspname in ('public','dv_market_private','dv_v16_private','battle_spectator_private','battle_spectator_media_private','dv_collect_private') or n.oid is null) group by n.nspname,d.defaclrole,d.defaclobjtype
 ) select jsonb_agg(jsonb_build_array(k,name,md5(v::text)) order by k collate "C",name collate "C") from checks into actual;
 return jsonb_build_object('revision','privilege-mfa-v1','compatible',coalesce(actual=$catalog$[["defaults","GLOBAL.postgres.f","29e66cd4ef686ad75c71dea7c11e1862"],["defaults","public.postgres.S","fa112ad909ac7fddc65b6d7e317fb207"],["defaults","public.postgres.f","29e66cd4ef686ad75c71dea7c11e1862"],["defaults","public.postgres.r","6b25047752475584e9e0f330a6dfaa23"],["function","battle_spectator_media_private.close_epoch(p_match uuid, p_reason text)","47193e837496e5dd598b8c064af5dec4"],["function","battle_spectator_media_private.sync_epoch(p_match uuid)","2d0f544b5c5dbfb48db2cc9f9b0563d1"],["function","battle_spectator_private.actor_session(p_require_eligible boolean)","053d2338a940812c3281602fcd95587d"],["function","battle_spectator_private.authorized(p_match uuid, p_uid uuid)","f1f9bcecb8ad33903dc8940fd39c265e"],["function","battle_spectator_private.eligible(p_uid uuid)","43e6036354d9b05d9cf22a257a58a839"],["function","battle_spectator_private.guard_match_write()","ddc406784f1be7853e2a30b04ae6fc44"],["function","battle_spectator_private.snapshot(p_match uuid)","346fd9ada8a0a061aa25eb301b522c69"],["function","battle_spectator_private.viewer_count(p_match uuid)","11c2482e3b013e2040ddaa4be85c5ea2"],["function","dv_collect_private.delete_empty_binder(p_folder_id uuid)","18f28bbc286e94d0834b46f7748b45f1"],["function","dv_market_private.account_deletion_blockers(p_uid uuid)","ea48c029bea4b68dba7574d14366b223"],["function","dv_market_private.audit_market_seller_account()","d65033ed42d6b093843e91930995edc3"],["function","dv_market_private.b07_add_workdays_de(p_start timestamp with time zone, p_days integer)","4b6cfab1e324ce41645c5845df5b6e36"],["function","dv_market_private.b07_complete_order(p_order_id uuid, p_reason text, p_completed_at timestamp with time zone)","36fb76c01ad6b0a2c772cd1951ec1db2"],["function","dv_market_private.b07_release1_shipping_windows()","ca7c9731c2bbf31ddd66754b4a32c1bb"],["function","dv_market_private.b07_set_shipping_due()","2f520ff171239175127